'数码办公':['增值税电子普通发票_京东_显示器.pdf'],
'交通出行':['滴滴出行电子发票_10月.pdf'],
'餐饮':['餐饮发票_2026-09-12.pdf']}
original={f.name:hashlib.sha256(f.read_bytes()).hexdigest() for f in base.iterdir() if f.is_file() and f.stat().st_size<1000000}
plan=[]
for category,names in groups.items():
 for name in names:
  src=base/name; dst=root/category/name
  if not src.is_file(): raise RuntimeError(f'Missing source: {src}')
  if dst.exists(): raise RuntimeError(f'Destination exists: {dst}')
  plan.append((src,dst,original[name]))
for src,dst,digest in plan:
 dst.parent.mkdir(parents=True,exist_ok=True)
 src.rename(dst)
 assert hashlib.sha256(dst.read_bytes()).hexdigest()==digest
 assert not src.exists()
 print('MOVED',dst)
moved={src.name for src,dst,digest in plan}
for name,digest in original.items():
 if name not in moved:
  assert hashlib.sha256((base/name).read_bytes()).hexdigest()==digest
print('VERIFIED',len(plan),'files moved, remaining small files unchanged; large files untouched')
print('ARCHIVE',root)

