import urllib.request, json
try:
    r = urllib.request.urlopen("https://wttr.in/Shanghai?format=j1", timeout=25)
    d = json.loads(r.read().decode())
    for day in d["weather"][:3]:
        print(day["date"], day["mintempC"], day["maxtempC"], day["avgtempC"])
        for h in day["hourly"][::2]:
            print("   ", h["time"], h["weatherDesc"][0]["value"], h["tempC"], "C", "降水", h["precipMM"], "mm", "体感", h["FeelsLikeC"], "湿度", h["humidity"])
except Exception as e:
    print("ERR", type(e).__name__, e)

